# Completa la línea marcada y compruébala con py check.
def exactitud(salidas, oro, campo):
    bien = 0
    for s, o in zip(salidas, oro):
        bien += 0   # ← cambia esta línea: 1 si s[campo] coincide con o[campo]
    return bien / len(oro)

print(exactitud([{"urgencia": "alta"}, {"urgencia": "media"}], [{"urgencia": "alta"}, {"urgencia": "baja"}], "urgencia"))   # 0.5
